import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { AiSpecializationComponent } from '../ai-specialization/ai-specialization.component';
import { FooterComponent } from '../footer/footer.component';
import { HeaderComponent } from '../header/header.component';
import { HeroComponent } from '../hero/hero.component';
import { TeamComponent } from '../team/team.component';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, HeaderComponent, HeroComponent, TeamComponent, AiSpecializationComponent, FooterComponent],
  template: `
    <app-header></app-header>
    <app-hero></app-hero>
    <app-team></app-team>
    <app-ai-specialization></app-ai-specialization>
    <!-- Other sections/components will be added here in next steps -->
    <app-footer></app-footer>
  `,
  styles: []
})
export class HomeComponent implements OnInit {
  ngOnInit(): void {}
}
